INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rev_9f7f6e9c9c0506700d', 'm_nnsfkbkt', 'reviewer_0_0', 2, 'The open status was confirmed through the platform before arriving, and the on-site situation matched the page; queue time still needs to be allowed for during peak hours. The visit took place on a weekday evening, with queue duration specifically observed, so the visit was moved to an off-peak period.', '[]', '2026-03-03T10:00:00+08:00');
INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rev_b177679cc92413e606', 'm_nchfaggy', 'reviewer_0_1', 5, 'The cancellation rules are clearly stated, and temporary rescheduling can be handled on the page; booking and payment on the user''s behalf are not provided. The visit took place on a Saturday morning, with lighting uniformity specifically observed, so the plan for that day was canceled.', '[]', '2026-03-09T11:17:00+08:00');
INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rev_31dee4208a91e07552', 'm_ukwjdkqy', 'reviewer_0_2', 4, 'Beginners can complete the basic experience, but the coach focuses more on course sales, so authorization boundaries must be maintained. The visit took place on a rainy afternoon, with rest seating specifically observed, so it was recorded in the long-term log.', '[]', '2026-03-13T12:34:00+08:00');
INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rev_670d5e6b0f7e28af8f', 'm_rscgngag', 'reviewer_0_3', 3, 'The most recent visit could not be used because an event occupied the space, and the platform subsequently updated the availability information. The visit took place before a holiday, with equipment maintenance specifically observed, so only a short session was scheduled.', '[]', '2026-03-18T13:01:00+08:00');
INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rev_4c78585c4fad79b349', 'm_dkqesmnl', 'reviewer_0_4', 2, 'Public transportation is convenient, but the evening lighting is average, making it suitable for short-term use rather than extended training. The visit took place on a league event day, with indoor ventilation specifically observed, so no package was purchased.', '[]', '2026-03-23T14:18:00+08:00');
INSERT INTO reviews (review_id, merchant_id, user_id, rating, body, image_captions, created_at) VALUES ('rev_ae7d6b2db50dbadc5b', 'm_bonwbdqk', 'reviewer_0_5', 5, 'Low-price periods are limited, and the prices shown on the page exclude additional services; the latest terms should be checked before arriving. The visit took place on an ordinary weekday, with the cancellation entry specifically observed, so an alternative venue was retained.', '[]', '2026-03-28T15:35:00+08:00');
